import { useEffect, useState } from 'react';
import { Chart } from 'primereact/chart';
import { getMetrics } from '../services/api';

const metricLabels = {
  temperature: 'Температура (°C)',
  humidity: 'Вологість (%)',
  light: 'Освітлення (lx)',
  pressure: 'Тиск (гПа)',
  air_quality: 'Якість повітря (PM2.5, мкг/м³)',
  co2: 'CO₂ (ppm)',
  wind_speed: 'Швидкість вітру (м/с)',
  noise_level: 'Рівень шуму (дБ)',
  battery: 'Заряд батареї (%)'
};

// Мапінг назв метрик з App на типи в API
const metricTypeMapping = {
  'Температура': 'temperature',
  'Вологість': 'humidity',
  'Освітлення': 'light',
  'Тиск': 'pressure',
  'Якість повітря': 'air_quality',
  'СО2': 'co2',
  'Швидкість вітру': 'wind_speed',
  'Рівень шуму': 'noise_level',
  'Заряд батареї': 'battery'
};

export default function MetricsChart({ deviceId, dateRange, metricTypes }) {
  const [metricsByType, setMetricsByType] = useState({});

  useEffect(() => {
    if (!deviceId) return;

    // Перетворюємо назви метрик у відповідні типи для API
    const apiMetricTypes = metricTypes.map(type => metricTypeMapping[type]);

    // Формуємо параметри запиту
    const params = { deviceId };
    if (dateRange && dateRange[0]) params.startDate = dateRange[0].toISOString();
    if (dateRange && dateRange[1]) params.endDate = dateRange[1].toISOString();
    if (apiMetricTypes.length > 0) params.types = apiMetricTypes;

    getMetrics(params).then((metrics) => {
      const grouped = {};

      for (const metric of metrics) {
        const { type, value, timestamp } = metric;
        if (!grouped[type]) grouped[type] = { labels: [], data: [] };

        grouped[type].labels.push(new Date(timestamp).toLocaleTimeString());
        grouped[type].data.push(value);
      }

      setMetricsByType(grouped);
    }).catch(error => console.error('Помилка завантаження метрик:', error));
  }, [deviceId, dateRange, metricTypes]);

  if (!deviceId) {
    return <div className="card">Виберіть пристрій для перегляду метрик</div>;
  }

  if (Object.keys(metricsByType).length === 0) {
    return <div className="card">Немає даних для відображення</div>;
  }

  return (
    <div className="grid">
      {Object.entries(metricsByType).map(([type, { labels, data }]) => (
        <div className="col-12 md:col-6" key={type}>
          <div className="card">
            <h4>{metricLabels[type] || type}</h4>
            <Chart
              type="line"
              data={{
                labels,
                datasets: [{
                  label: metricLabels[type] || type,
                  data,
                  borderColor: '#42A5F5',
                  fill: false,
                }],
              }}
              options={{
                responsive: true,
                plugins: {
                  legend: { position: 'top' },
                },
                scales: {
                  x: {
                    ticks: {
                      autoSkip: true,
                      maxTicksLimit: 10 // Обмежуємо кількість міток на осі X
                    }
                  }
                }
              }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}
